'use strict';
const api=location.pathname.startsWith('/online/')?'./api/index.php':'../api/index.php';
const steps=[['BOOKED','ยืนยันการจอง'],['REGISTRATION_WAITING','รอห้องบัตร'],['REGISTRATION_CALLED','เจ้าหน้าที่เรียก'],['REGISTRATION_IN_PROGRESS','กำลังเปิด Visit'],['SENT_TO_DEPARTMENT','ส่งไปยังแผนกแล้ว']];
const titles={BOOKED:'จองคิวเรียบร้อยแล้ว',REGISTRATION_WAITING:'กำลังรอห้องบัตร',REGISTRATION_CALLED:'เจ้าหน้าที่ห้องบัตรเรียกแล้ว',REGISTRATION_IN_PROGRESS:'กำลังลงทะเบียนและเปิด Visit',SENT_TO_DEPARTMENT:'เปิด Visit และส่งแผนกแล้ว'};
const BOOKING_STORE='kqonline_bookings_v1';
let activeToken='',activeReference='',scannerStream=null;
const $=id=>document.getElementById(id);
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]))}
function digits(value){return String(value||'').replace(/\D/g,'')}
function tokenFrom(value){const raw=String(value||'').trim();try{const url=new URL(raw);return url.searchParams.get('t')||url.pathname.split('/').filter(Boolean).pop()||raw}catch{return raw}}
function thaiDate(value){if(!value)return '—';const d=new Date(value.includes('T')?value:`${value}T12:00:00+07:00`);return new Intl.DateTimeFormat('th-TH-u-ca-buddhist',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Bangkok'}).format(d)}
function currentIndex(step){const aliases={WAITING:'REGISTRATION_WAITING',CALLED:'REGISTRATION_CALLED',CHECKED_IN:'REGISTRATION_WAITING',SERVING:'REGISTRATION_IN_PROGRESS',COMPLETED:'SENT_TO_DEPARTMENT'};return Math.max(0,steps.findIndex(x=>x[0]===(aliases[step]||step)))}
function savedBookings(){try{return JSON.parse(localStorage.getItem(BOOKING_STORE)||'[]').filter(item=>item?.public_id)}catch{return []}}
async function reconcileSavedBookings(){const items=savedBookings();if(!items.length)return items;const checks=await Promise.all(items.map(async item=>{try{const response=await fetch(`${api}?action=queue-status&token=${encodeURIComponent(item.public_id)}`,{cache:'no-store'});return response.status===404?null:item}catch{return item}}));const valid=checks.filter(Boolean);if(valid.length!==items.length)localStorage.setItem(BOOKING_STORE,JSON.stringify(valid));return valid}
function renderSavedQueues(){const items=savedBookings();if(!items.length)return;$('savedQueues').innerHTML=`<strong>คิวที่บันทึกไว้ในเครื่องนี้</strong>${items.slice(0,5).map((item,index)=>{const start=String(item.start_time||'').slice(0,5),end=String(item.end_time||'').slice(0,5),slot=start&&end?` · ${start}–${end} น.`:'';return `<button class="saved-queue" type="button" data-saved="${index}"><strong>${escapeHtml(item.reference_no||'รายการจอง')} · ${escapeHtml(item.department_name||'')}</strong><span>${item.slot_date?thaiDate(item.slot_date)+slot:'แตะเพื่อตรวจสอบสถานะล่าสุด'}</span></button>`}).join('')}`;$('savedQueues').classList.remove('hidden');$('savedQueues').querySelectorAll('[data-saved]').forEach(button=>button.onclick=()=>loadStatus(items[+button.dataset.saved].public_id))}
async function requestLookup(method,value){const response=await fetch(`${api}?action=kiosk-lookup`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({method,value})});const body=await response.json();if(!response.ok)throw new Error(body.error||'ค้นหาคิวไม่สำเร็จ');return body.data||[]}
async function linkHosxp(row,citizenId){if(!row.queue_public_id)return;await fetch(`${api}?action=hosxp-link`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:row.queue_public_id,citizen_id:citizenId})}).catch(()=>{})}
async function openMatch(row,method,value){if(method==='citizen')await linkHosxp(row,digits(value));await loadStatus(row.queue_public_id||row.public_id)}
function renderMatches(rows,method,value){$('lookupMatches').classList.remove('hidden');$('lookupMatches').innerHTML=`<p>พบ ${rows.length} รายการ เลือกคิวที่ต้องการตรวจสอบ</p>${rows.map((row,index)=>`<button class="lookup-match" type="button" data-match="${index}"><strong>${escapeHtml(row.queue_no||row.reference_no)} · ${escapeHtml(row.department_name)}</strong><span>${escapeHtml(row.customer_display)} · ${String(row.start_time).slice(0,5)}–${String(row.end_time).slice(0,5)} น.</span></button>`).join('')}`;$('lookupMatches').querySelectorAll('[data-match]').forEach(button=>button.onclick=()=>openMatch(rows[+button.dataset.match],method,value))}
async function resolveStatus(value){const raw=tokenFrom(value);$('lookupError').classList.add('hidden');$('lookupMatches').classList.add('hidden');if(/^[a-f0-9]{32}$/i.test(raw)){await loadStatus(raw.toLowerCase());return}const cid=digits(raw),method=cid.length===13?'citizen':'code';const rows=await requestLookup(method,method==='citizen'?cid:raw);if(!rows.length)throw new Error('ไม่พบคิวของวันนี้ กรุณาตรวจสอบข้อมูลอีกครั้ง');if(rows.length===1){await openMatch(rows[0],method,method==='citizen'?cid:raw);return}renderMatches(rows,method,method==='citizen'?cid:raw)}
async function loadHosxpStatus(token){try{const response=await fetch(`${api}?action=hosxp-status&token=${encodeURIComponent(token)}`,{cache:'no-store'});if(!response.ok)return;const body=await response.json(),state=body.data;if(!state?.enabled)return;if(state.visit_found){$('statusTitle').textContent='ลงทะเบียน HOSxP แล้ว';$('waitTime').textContent='พบ Visit ของวันนี้';$('nextAction').textContent=state.current_department?`สถานะล่าสุด: ${state.current_department}`:'กำลังตรวจสอบจุดบริการใน HOSxP'}else if(state.sync_status==='WAITING_FOR_VISIT'){$('waitTime').textContent='ยังไม่พบ Visit ใน HOSxP';$('nextAction').textContent='กรุณารอเจ้าหน้าที่ห้องบัตรลงทะเบียนเปิด Visit'}else if(state.sync_status==='PATIENT_NOT_FOUND'){$('waitTime').textContent='ยังไม่พบข้อมูลผู้รับบริการใน HOSxP'}else if(state.sync_status==='ERROR'){$('nextAction').textContent='เชื่อมต่อ HOSxP ไม่สำเร็จชั่วคราว ระบบคิวยังใช้งานได้ตามปกติ'}}catch{}}
async function loadStatus(token){activeToken=tokenFrom(token);$('lookupError').classList.add('hidden');try{const response=await fetch(`${api}?action=queue-status&token=${encodeURIComponent(activeToken)}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error||'ไม่พบข้อมูลคิว');render(body.data);activeToken=body.data.token||activeToken;loadHosxpStatus(activeToken);history.replaceState(null,'',`?t=${encodeURIComponent(activeToken)}`)}catch(error){$('lookupCard').classList.remove('hidden');$('statusCard').classList.add('hidden');$('lookupError').textContent=error.message;$('lookupError').classList.remove('hidden')}}
function render(data){$('lookupCard').classList.add('hidden');$('statusCard').classList.remove('hidden');activeReference=data.reference_no||'';$('showCheckinQr').classList.toggle('hidden',data.current_step!=='BOOKED');$('queueNo').textContent=data.queue_no||'ยังไม่ออกคิว';$('customer').textContent=data.customer_display;$('location').textContent=`${data.branch_name} · ${data.department_name}`;$('service').textContent=data.service_name||data.department_name;const start=String(data.start_time||'').slice(0,5),end=String(data.end_time||'').slice(0,5);$('reference').textContent=`${data.reference_no} · เริ่มส่งตรวจ ${thaiDate(data.slot_date)} เวลา ${start}–${end} น.`;$('statusTitle').textContent=titles[data.current_step]||'กำลังดำเนินการ';$('waitTime').textContent=data.current_step==='SENT_TO_DEPARTMENT'?'ส่งต่อแล้ว':data.estimated_wait_minutes===null?'กำลังประเมิน':data.estimated_wait_minutes<=0?'ใกล้ถึงคิว':`ประมาณ ${data.estimated_wait_minutes} นาที`;$('nextAction').textContent=data.current_step==='BOOKED'?'กรุณากดแสดง QR แล้วสแกนรับบัตรคิวที่ Kiosk':data.current_step==='SENT_TO_DEPARTMENT'?'กรุณาไปยังแผนกตามที่เจ้าหน้าที่แจ้ง':'โปรดรอเจ้าหน้าที่ห้องบัตรเรียกตามหมายเลขคิว';const index=currentIndex(data.current_step);$('timeline').innerHTML=steps.map((s,i)=>`<li class="step ${i<index?'done':i===index?'current':''}"><div class="step-mark">${i<index?'✓':i+1}</div><div><strong>${s[1]}</strong><span>${i<index?'ดำเนินการแล้ว':i===index?'ขั้นตอนปัจจุบัน':'รอดำเนินการ'}</span></div></li>`).join('')}
$('lookupForm').onsubmit=async event=>{event.preventDefault();const submit=event.submitter;submit.disabled=true;submit.textContent='กำลังค้นหา…';try{await resolveStatus($('tokenInput').value)}catch(error){$('lookupError').textContent=error.message;$('lookupError').classList.remove('hidden')}finally{submit.disabled=false;submit.textContent='ค้นหาและดูสถานะ'}};
$('refreshButton').onclick=()=>loadStatus(activeToken);$('newLookup').onclick=()=>{history.replaceState(null,'',location.pathname);$('statusCard').classList.add('hidden');$('lookupCard').classList.remove('hidden');$('lookupMatches').classList.add('hidden');$('tokenInput').value='';$('tokenInput').focus()};
function closeCheckinQr(){$('checkinQrDialog').classList.add('hidden')}
$('showCheckinQr').onclick=()=>{if(!activeToken)return;const url=new URL('status.html',location.href);url.search='';url.searchParams.set('t',activeToken);const qr=qrcode(0,'M');qr.addData(url.href);qr.make();$('checkinQrImage').src=qr.createDataURL(8,12);$('checkinQrReference').textContent=activeReference||'—';$('checkinQrDialog').classList.remove('hidden')};$('closeCheckinQr').onclick=closeCheckinQr;$('closeCheckinQrButton').onclick=closeCheckinQr;$('checkinQrDialog').onclick=event=>{if(event.target===$('checkinQrDialog'))closeCheckinQr()};
function stopScanner(){if(scannerStream){scannerStream.getTracks().forEach(track=>track.stop());scannerStream=null}$('scannerVideo').srcObject=null}
function closeScanner(){stopScanner();$('scannerDialog').classList.add('hidden')}
async function openScanner(){$('scannerDialog').classList.remove('hidden');$('scannerError').classList.add('hidden');try{scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});$('scannerVideo').srcObject=scannerStream;await $('scannerVideo').play();const detector='BarcodeDetector'in window?new BarcodeDetector({formats:['qr_code']}):null,canvas=document.createElement('canvas'),context=canvas.getContext('2d',{willReadFrequently:true});let lastFallback=0;const scan=async time=>{if(!scannerStream)return;let value='';if(detector){const codes=await detector.detect($('scannerVideo')).catch(()=>[]);value=codes[0]?.rawValue||''}else if(typeof jsQR==='function'&&time-lastFallback>120&&$('scannerVideo').videoWidth){lastFallback=time;canvas.width=$('scannerVideo').videoWidth;canvas.height=$('scannerVideo').videoHeight;context.drawImage($('scannerVideo'),0,0,canvas.width,canvas.height);const image=context.getImageData(0,0,canvas.width,canvas.height);value=jsQR(image.data,image.width,image.height,{inversionAttempts:'dontInvert'})?.data||''}if(value){closeScanner();$('tokenInput').value=tokenFrom(value);try{await resolveStatus(value)}catch(error){$('lookupError').textContent=error.message;$('lookupError').classList.remove('hidden')}return}requestAnimationFrame(scan)};requestAnimationFrame(scan)}catch(error){stopScanner();$('scannerError').textContent='ไม่สามารถเปิดกล้องได้ กรุณาอนุญาตการใช้กล้อง หรือกรอกรหัสแทน';$('scannerError').classList.remove('hidden')}}
$('scanQrButton').onclick=openScanner;$('startScanner').onclick=openScanner;$('closeScanner').onclick=closeScanner;$('scannerDialog').onclick=event=>{if(event.target===$('scannerDialog'))closeScanner()};document.querySelectorAll('[data-status-tab]').forEach(button=>button.onclick=()=>{const action=button.dataset.statusTab;if(action==='refresh'&&activeToken){loadStatus(activeToken);return}$('statusCard').classList.add('hidden');$('lookupCard').classList.remove('hidden');$('tokenInput').focus()});
function updateClock(){$('clock').textContent=new Intl.DateTimeFormat('th-TH-u-ca-buddhist',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'Asia/Bangkok'}).format(new Date())+' น.'}
updateClock();setInterval(updateClock,30000);reconcileSavedBookings().then(renderSavedQueues).catch(renderSavedQueues);const initial=new URLSearchParams(location.search).get('t');if(initial)loadStatus(initial);
